const tabId = 1148881640;

const details = await browserjs(tabId, () => {
  // Let's find each product container
  const h3Elements = Array.from(document.querySelectorAll('h3'));
  return h3Elements.map(h3 => {
    // Traverse up to find product card container
    let container = h3;
    while (container && container.tagName !== 'BODY') {
      if (container.tagName === 'LI' || container.getAttribute('data-sku-id') || container.className.includes('sku-item') || container.className.includes('product-item')) {
        break;
      }
      container = container.parentElement;
    }
    const fullText = container ? container.innerText : '';
    // Look for price pattern like $XX.XX
    const priceMatches = fullText.match(/\$[0-9,]+(\.[0-9]{2})?/g);
    return {
      title: h3.innerText.trim(),
      prices: priceMatches,
      containerTag: container ? container.tagName : null,
      containerClass: container ? container.className : null,
      fullText: fullText.slice(0, 500)
    };
  });
});

